update public.learning_paths
set
  title = 'Site Planning and Landscape',
  goal = 'Site Planning and Landscape',
  summary = 'Students learn that site is not background scenery; it is a set of physical, ecological, social, infrastructural, legal, and experiential forces that shape architecture. The course covers inventory and mapping, landform and accessible grading, water-sensitive design, living systems and planting, program and circulation, hardscape and outdoor comfort, urban and regional systems, regulation and feasibility, climate and equity, representation, and community, synthesized as an integrated site strategy.',
  data = $sitejson${"slug": "site-planning-and-landscape", "title": "Site Planning and Landscape", "description": "Students learn that site is not background scenery; it is a set of physical, ecological, social, infrastructural, legal, and experiential forces that shape architecture. The course covers inventory and mapping, landform and accessible grading, water-sensitive design, living systems and planting, program and circulation, hardscape and outdoor comfort, urban and regional systems, regulation and feasibility, climate and equity, representation, and community, synthesized as an integrated site strategy.", "topics": [{"id": "cf061be7-ac6f-45a6-bb17-a55dcb69ed58", "type": "topic", "title": "Site Planning as Architectural Groundwork: Observation, Scale, Context, and Design Intent", "description": "Students learn that site is not background scenery; it is a set of physical, ecological, social, infrastructural, legal, and experiential forces that shape architecture from the first sketch.", "children": [{"id": "e67a9e7a-aa09-4946-971f-a2ff363377c5", "type": "subtopic", "title": "Site as active design agent", "children": [{"id": "3e6e1be5-758c-40af-91ad-888e5559f456", "type": "concept", "title": "Ground, climate, ecology, infrastructure, law, memory, and use"}, {"id": "71e37459-efb6-419c-b57b-233303e21b87", "type": "concept", "title": "Site response versus site imposition"}, {"id": "5cca9a89-3eea-497c-a02b-7ef92c4b6487", "type": "concept", "title": "Architecture, landscape, and urbanism as one system"}], "description": "Students learn to treat site conditions as generators of architecture, not limits to be added after the fact."}, {"id": "41b7c307-9613-4ea6-8493-9b91388c4ad3", "type": "subtopic", "title": "Scales of site thinking", "children": [{"id": "d9777e84-6aa9-4afd-9e39-ae4a614dd56e", "type": "concept", "title": "Lot, block, district, watershed, corridor, city, and region"}, {"id": "28ea4922-6a47-4f7b-a346-2b33ba9f919f", "type": "concept", "title": "Immediate context and long-term transformation"}, {"id": "b10a6231-89cc-4b3c-a36f-28caa9e04e93", "type": "concept", "title": "Nested systems and design consequences"}], "description": "The point is to connect parcel-level decisions to neighborhood and regional systems."}, {"id": "95b6f464-310d-4c4e-8def-3c7d959d9d23", "type": "subtopic", "title": "Design intent from evidence", "children": [{"id": "853e029a-f98c-4a17-9ddf-a4181a333836", "type": "concept", "title": "Site questions, hypotheses, constraints, opportunities, and performance goals"}, {"id": "56f7f0b0-2900-4a6a-b95e-203559c3afa9", "type": "concept", "title": "Evidence-based concept development"}, {"id": "622be3ab-45f4-4c38-9203-ecc70021afb5", "type": "concept", "title": "From analysis to action"}], "description": "Students learn to derive design priorities from observable conditions."}]}, {"id": "5a279555-b85a-4a11-b483-cfe44be4afd9", "type": "topic", "title": "Site Inventory and Analysis: Fieldwork, Mapping, Climate, Context, Access, and Constraints", "description": "This module teaches students to gather, map, and interpret site evidence before making design claims.", "children": [{"id": "ff7f1f00-4af4-4d01-b6e8-8bd775ab6201", "type": "subtopic", "title": "Field observation", "children": [{"id": "7547c5fe-f617-455b-bc8b-d4121796b165", "type": "concept", "title": "Photographs, sketches, measurements, sensory notes, use patterns, and time-of-day observations"}, {"id": "d040ab6f-4325-4d69-ac3d-40f0257a602d", "type": "concept", "title": "Weather, shade, noise, smell, wind, edges, and desire lines"}, {"id": "e33b01d4-e2ad-4283-85fb-1bf6179e6bd4", "type": "concept", "title": "Field ethics and safety"}], "description": "Students practice direct site reading before abstract mapping."}, {"id": "059deff4-fb05-483e-8840-a37eba81c633", "type": "subtopic", "title": "Mapping and layers", "children": [{"id": "524eecc6-fb6e-41f4-9445-105ddd738177", "type": "concept", "title": "Base maps, figure-ground, land use, access, hydrology, vegetation, utilities, and microclimate"}, {"id": "d808b648-ec96-4189-832e-ea11fd1868eb", "type": "concept", "title": "Opportunities, constraints, and conflicts"}, {"id": "95f27913-aa77-4712-b764-b87c51e4e847", "type": "concept", "title": "Overlay analysis and hierarchy"}], "description": "The gist is to transform raw observations into legible site intelligence."}, {"id": "ad3abd10-6949-4414-9ed3-4b89d7865cc9", "type": "subtopic", "title": "Context interpretation", "children": [{"id": "06d71fff-2ecf-4c7e-a579-60bb5a44a447", "type": "concept", "title": "History, neighborhood form, mobility, demographics, ownership, and adjacent programs"}, {"id": "34098eac-e8ac-478f-ab3a-a6079fdcd2c2", "type": "concept", "title": "Views, landmarks, thresholds, and public/private gradients"}, {"id": "841354c7-30b6-4bfe-bde8-77bb5097a708", "type": "concept", "title": "Critical reading of assumptions"}], "description": "Students learn to connect site facts to design implications."}]}, {"id": "d94bd66f-9df4-4fbc-9c96-3fdde06da2b2", "type": "topic", "title": "Topography, Contours, Grading, Earthwork, Slopes, and Accessible Landform", "description": "Students learn how landform affects movement, drainage, cost, accessibility, foundations, views, and outdoor experience.", "children": [{"id": "48300b1d-ade3-428b-9250-0bf4f0171c91", "type": "subtopic", "title": "Contour literacy", "children": [{"id": "bc1c634d-d0d7-4f62-a2e6-5cb0379faed6", "type": "concept", "title": "Contour intervals, spot elevations, slope percentages, ridges, valleys, high points, and low points"}, {"id": "c9d04adb-8fde-49a0-926d-a4eb54cf6ad1", "type": "concept", "title": "Cut, fill, retaining conditions, and drainage direction"}, {"id": "3f19e224-97d1-4bdd-85bd-59e6c63f5f18", "type": "concept", "title": "Sections as topographic evidence"}], "description": "Students learn to read and draw landform accurately."}, {"id": "e7d7489a-29eb-4139-823f-ef1084a5222c", "type": "subtopic", "title": "Grading design", "children": [{"id": "8a5f2716-3ca3-4c07-9f72-b50f42327abf", "type": "concept", "title": "Pads, terraces, swales, berms, ramps, stairs, walls, and transitions"}, {"id": "73dba7ff-047e-47a0-848e-30b9239ce381", "type": "concept", "title": "Balancing earthwork and minimizing disturbance"}, {"id": "5db9fd82-3966-4f41-9e88-ce356ec78cca", "type": "concept", "title": "Grading plans and spot elevations"}], "description": "The point is to shape landform for use, drainage, constructability, and experience."}, {"id": "cfd80766-ec10-466e-9bf0-9b119f77dcbc", "type": "subtopic", "title": "Accessible landform", "children": [{"id": "4257dbee-98ce-49d3-9c49-8d6179627a31", "type": "concept", "title": "Accessible routes, cross slope, running slope, landings, curb ramps, handrails, and detectable warnings"}, {"id": "393b06e3-8e00-4661-97a0-1b69c155eed6", "type": "concept", "title": "Universal access through terrain"}, {"id": "cefcfab0-1ec4-42b1-b48a-994e96f04975", "type": "concept", "title": "Avoiding leftover accessibility paths"}], "description": "Students connect grading to inclusive movement."}]}, {"id": "609309c7-ef0c-4d41-80fa-82d5da56e550", "type": "topic", "title": "Hydrology, Stormwater, Green Infrastructure, Watersheds, and Water-Sensitive Design", "description": "This topic introduces water as a design system, from rainfall and runoff to infiltration, detention, water quality, and resilience.", "children": [{"id": "36769b21-13e4-4512-a81f-a2473bb0227e", "type": "subtopic", "title": "Water movement", "children": [{"id": "97f89130-27bc-4187-bd43-c0d4d66ffebe", "type": "concept", "title": "Watersheds, subcatchments, runoff, infiltration, evapotranspiration, and groundwater"}, {"id": "14616733-6d8c-45a7-9570-39331ee6acee", "type": "concept", "title": "Impervious surfaces and time of concentration"}, {"id": "e0a47a64-0fad-4e3c-bc9b-11f78f5ecdd3", "type": "concept", "title": "Flooding, erosion, and downstream impacts"}], "description": "Students understand how water enters, crosses, and leaves a site."}, {"id": "177ee1bb-7ab1-438e-aac7-66b9f9f23fc4", "type": "subtopic", "title": "Stormwater strategies", "children": [{"id": "8bda5b8f-ac28-48d9-a740-91d9c8f2ec79", "type": "concept", "title": "Bioswales, rain gardens, detention, retention, permeable paving, cisterns, green roofs, and constructed wetlands"}, {"id": "771478b6-7303-4634-9509-3581fcc12c4a", "type": "concept", "title": "Water quality and first flush"}, {"id": "b362296f-e720-46cd-a71c-454054a57ed3", "type": "concept", "title": "Maintenance and performance tradeoffs"}], "description": "The gist is to use water management as design structure."}, {"id": "7d546c41-2ebb-473b-bc08-ff5e035d7acc", "type": "subtopic", "title": "Resilience and regulation", "children": [{"id": "dcd9e647-240d-4ac3-9d66-c58b751fbe74", "type": "concept", "title": "Floodplains, storm events, sea-level rise, combined sewer overflow, and local stormwater ordinances"}, {"id": "f00c1329-ac06-43f4-b9d9-b34090c3e400", "type": "concept", "title": "Low-impact development and green infrastructure"}, {"id": "bdff8003-7a3a-482a-aa05-93f140f6167a", "type": "concept", "title": "Documenting stormwater concepts in design packages"}], "description": "Students connect hydrology to climate and approvals."}]}, {"id": "2bb09edc-aba1-43fa-89f6-2c949d0cdca5", "type": "topic", "title": "Ecology, Soils, Vegetation, Habitat, Planting Design, and Landscape Performance", "description": "Students study living systems as design material and performance infrastructure rather than decoration.", "children": [{"id": "7ea9e89a-af12-4127-a84e-86c49d7aded4", "type": "subtopic", "title": "Soils and living systems", "children": [{"id": "5c1ade35-ac96-4a85-8ee6-fb6c7a623d80", "type": "concept", "title": "Soil texture, compaction, drainage, organic matter, contamination, and remediation"}, {"id": "c5b10ba1-e15a-4eaa-94e7-653ed44d39f8", "type": "concept", "title": "Root zones, soil volumes, and urban soil constraints"}, {"id": "ad271f05-e432-48d4-872d-55fb66e6d562", "type": "concept", "title": "Testing and interpretation"}], "description": "Students learn that soil is infrastructure for plants, water, carbon, and habitat."}, {"id": "b52a9a2f-57a2-4728-b685-54fb3bdcfee0", "type": "subtopic", "title": "Planting design", "children": [{"id": "903a9187-5a56-481d-ac84-4d98855fdbae", "type": "concept", "title": "Native/adapted plants, canopy, understory, groundcover, seasonality, succession, and maintenance"}, {"id": "0edd1c7e-7d3f-48f2-9a1e-86a8a4b6b5e2", "type": "concept", "title": "Biodiversity, habitat, pollinators, and invasive species"}, {"id": "50f9560f-7f8d-43de-8b77-636abba6ba48", "type": "concept", "title": "Planting plans and schedules"}], "description": "The point is to choose vegetation for ecological function, climate fit, and spatial experience."}, {"id": "1dc71ad4-8d68-4f89-b8df-3d5ece05d6e3", "type": "subtopic", "title": "Landscape performance", "children": [{"id": "7c41d913-0fec-45f7-a7a3-de5624fdb456", "type": "concept", "title": "Shade, heat reduction, stormwater capture, carbon, habitat, health, and social use"}, {"id": "bdeced8c-5f63-4480-a455-58a2fe875d8f", "type": "concept", "title": "Performance metrics and case-study evidence"}, {"id": "0e9f46ae-d0dd-4250-86ef-dcd9753a3644", "type": "concept", "title": "Post-occupancy evaluation"}], "description": "Students learn to measure landscape benefits."}]}, {"id": "fd13411c-a0d3-48b6-a7dd-b2ec9d89fd3d", "type": "topic", "title": "Site Planning Principles: Program, Adjacency, Circulation, Thresholds, and Spatial Organization", "description": "This module connects building program to exterior rooms, movement systems, arrival sequences, service access, and site logic.", "children": [{"id": "c41a16f9-60eb-445a-a873-a991a1f04ec3", "type": "subtopic", "title": "Program on site", "children": [{"id": "9ae1d9f6-7522-4a96-9118-4a4b31c7a712", "type": "concept", "title": "Entries, service, outdoor rooms, event areas, parking, drop-off, storage, and support spaces"}, {"id": "9a375550-4e0d-4253-969a-f795f33fb350", "type": "concept", "title": "Public/private gradients and secure zones"}, {"id": "b63f4b2e-2722-4a7e-a2da-03e2c4defee1", "type": "concept", "title": "Program conflicts and synergies"}], "description": "Students learn to translate building program into exterior relationships."}, {"id": "2d96bb8d-cfa5-401c-b57f-dba6f7c32d36", "type": "subtopic", "title": "Circulation systems", "children": [{"id": "576aa251-1e06-48d0-ac48-1f8a550052fa", "type": "concept", "title": "Approach, arrival, wayfinding, desire lines, ADA routes, loading, and fire access"}, {"id": "c6ce45fa-b66c-45d9-8982-0b6ccd1a55a3", "type": "concept", "title": "Modal hierarchy and conflict reduction"}, {"id": "89e71408-30a9-4008-bf1c-b5d24fc66c83", "type": "concept", "title": "Movement as experience"}], "description": "The gist is to choreograph movement for pedestrians, cyclists, vehicles, service, and emergency access."}, {"id": "d900a3be-c03c-4bfd-8e5e-2d6e239f7618", "type": "subtopic", "title": "Thresholds and edges", "children": [{"id": "a6682f13-dc93-40af-a73a-57000991b544", "type": "concept", "title": "Porches, plazas, courtyards, arcades, stoops, terraces, fences, walls, and planting edges"}, {"id": "e3e1ba48-bd09-4b99-95e9-8648422870c4", "type": "concept", "title": "Interior/exterior continuity"}, {"id": "4baacb4f-c381-4b63-9ef4-565c70df8455", "type": "concept", "title": "Human scale and invitation"}], "description": "Students design transitions between building, landscape, and city."}]}, {"id": "2437276f-b8da-4650-9fd9-cd3bd3cc4f69", "type": "topic", "title": "Hardscape, Materials, Details, Furnishings, Lighting, and Site Construction", "description": "Students learn how paved surfaces, edges, walls, steps, ramps, furnishings, and lighting make outdoor spaces durable and usable.", "children": [{"id": "5e129006-88e0-491b-9888-500f7182c91a", "type": "subtopic", "title": "Paving and surfaces", "children": [{"id": "fd438205-03b6-40d9-95fb-dd154550734f", "type": "concept", "title": "Concrete, asphalt, unit pavers, gravel, decking, permeable paving, and stabilized surfaces"}, {"id": "58da9fc9-f5e8-4ed0-ae62-71eb30d1a26a", "type": "concept", "title": "Slip resistance, accessibility, joints, drainage, and durability"}, {"id": "64816f3c-13e7-4202-bdb0-e47fa86d4782", "type": "concept", "title": "Material life cycle and repair"}], "description": "Students learn how hardscape affects movement, water, heat, maintenance, and character."}, {"id": "30e19833-ecd6-4ebc-a66a-e2bd3c743959", "type": "subtopic", "title": "Site elements and details", "children": [{"id": "6c1f15de-4da3-4dd9-8eab-c316fe8a0546", "type": "concept", "title": "Walls, curbs, stairs, ramps, railings, benches, bollards, bike racks, planters, and trash/recycling"}, {"id": "c356dde3-6e66-4a7b-86c5-4c3450d58c23", "type": "concept", "title": "Details, tolerances, edges, and constructability"}, {"id": "a6d188da-9a5a-4fed-b459-ef1401ee5c87", "type": "concept", "title": "Coordination with civil and landscape drawings"}], "description": "The point is to make outdoor spaces usable and buildable."}, {"id": "ead6adaa-fa96-4eb7-9df7-fb88cac9658b", "type": "subtopic", "title": "Lighting and safety", "children": [{"id": "97b67a6f-fc49-4857-aeb7-5fc49d8e145c", "type": "concept", "title": "Pedestrian lighting, glare, dark sky, security, wayfinding, and energy"}, {"id": "d5bfbe96-62d0-4fb1-9e02-8c3d7b28ba65", "type": "concept", "title": "Lighting levels and fixture selection"}, {"id": "dfec65bb-b8e8-419e-8eef-53d8cf315536", "type": "concept", "title": "Crime prevention through environmental design"}], "description": "Students connect nighttime use to comfort, safety, and ecology."}]}, {"id": "432093f4-4426-40b9-948f-c36d61e90a44", "type": "topic", "title": "Outdoor Space Design: Human Comfort, Microclimate, Views, Sequence, Safety, and Everyday Use", "description": "This topic focuses on the experience of people using outdoor rooms in different seasons, times of day, and social conditions.", "children": [{"id": "7e4ec7cc-fac9-46d1-a5ff-28c399263042", "type": "subtopic", "title": "Microclimate and comfort", "children": [{"id": "727aa96c-2cb6-4b15-adbe-3dfad386e4da", "type": "concept", "title": "Sun, shade, wind, humidity, thermal comfort, seasonal change, and shelter"}, {"id": "cc90dbcd-12c9-4ad8-9958-6cef1a92ea51", "type": "concept", "title": "Trees, canopies, walls, water, and material albedo"}, {"id": "d03f3ff0-f779-44ae-8b96-4ac1df94489e", "type": "concept", "title": "Heat mitigation and cold-climate comfort"}], "description": "Students learn to design for bodies in weather."}, {"id": "a4c5e33c-30eb-4f0c-8b6b-cd077744f97e", "type": "subtopic", "title": "Experience and sequence", "children": [{"id": "225ef3d5-7a6e-4fc5-9d20-d2163500da71", "type": "concept", "title": "Arrival, compression/release, framed views, prospect/refuge, sound, smell, texture, and movement"}, {"id": "70ea61b2-694a-42e3-b8fd-afe3d37f2bc8", "type": "concept", "title": "Edges, centers, thresholds, and destinations"}, {"id": "83b6fe42-b6e3-4bf7-8e73-7bab80e7fca6", "type": "concept", "title": "Narrative without over-designing"}], "description": "The gist is to make outdoor space memorable and legible."}, {"id": "e11b5bdf-abaf-484f-94f1-ba4ded8133d3", "type": "subtopic", "title": "Social use and safety", "children": [{"id": "0949da9b-1561-4ad3-b315-2ec5f662870f", "type": "concept", "title": "Seating choice, visibility, inclusivity, play, gathering, rest, and informal use"}, {"id": "eb99fd40-462c-43cb-bd91-58f2d38f0e04", "type": "concept", "title": "Maintenance, surveillance, lighting, and stewardship"}, {"id": "58703f26-6b2e-4166-8066-19c5f91ab692", "type": "concept", "title": "Comfort across age, ability, and culture"}], "description": "Students design outdoor spaces that support everyday life."}]}, {"id": "7bec144e-3c74-4d21-9e05-1e6353b4fb23", "type": "topic", "title": "Urban Site Design: Streets, Blocks, Public Realm, Edges, Mixed Use, and Neighborhood Context", "description": "Students study sites as parts of larger urban systems, including streets, blocks, frontages, public space, and land-use patterns.", "children": [{"id": "c6efe687-b4a0-482b-9d58-c9c34c571c29", "type": "subtopic", "title": "Urban morphology", "children": [{"id": "8033145b-055c-4c81-9c7d-95daa334395a", "type": "concept", "title": "Blocks, parcels, streets, alleys, frontages, setbacks, landmarks, and open-space networks"}, {"id": "5a1f70eb-0d46-43b5-9db5-c5f4d9f4106d", "type": "concept", "title": "Density, grain, scale, and building typologies"}, {"id": "8c41d312-5661-47f6-a271-340d3b6a2f10", "type": "concept", "title": "Historic and contemporary patterns"}], "description": "Students learn to read the shape of cities around a site."}, {"id": "e7ecc9eb-205b-414a-9fb5-ec9ced2d4382", "type": "subtopic", "title": "Public realm design", "children": [{"id": "a931a8f2-9ac3-48c3-a7e7-69340139e94a", "type": "concept", "title": "Sidewalks, plazas, parks, transit stops, bike networks, street trees, and curb uses"}, {"id": "a1bac122-3f5f-4016-809b-d7a7e1909ffa", "type": "concept", "title": "Active edges, transparency, accessibility, and seating"}, {"id": "0f8628ab-a9fd-4041-b736-90bf81f346e5", "type": "concept", "title": "Public/private responsibility and maintenance"}], "description": "The point is to understand streets and open spaces as shared civic infrastructure."}, {"id": "9c6a3bf8-475d-43c6-8ddd-bae948c04517", "type": "subtopic", "title": "Mixed-use relationships", "children": [{"id": "21019c6c-4f8a-4c6f-9931-5ce4d4bca16e", "type": "concept", "title": "Ground-floor uses, loading, parking, housing, retail, institutions, and community facilities"}, {"id": "33ef2233-09d0-403e-9075-5e8635a58514", "type": "concept", "title": "Noise, privacy, security, and service access"}, {"id": "62c0f757-fe47-4add-a7d0-8d8a1f0d3698", "type": "concept", "title": "Urban design guidelines and placemaking"}], "description": "Students coordinate site design with urban program and neighborhood life."}]}, {"id": "023ae9b1-84f0-4093-a6a0-ebeae6b38d55", "type": "topic", "title": "Landscape Systems, Infrastructure, Mobility, Service Networks, and Regional Scales", "description": "This module expands site planning beyond the parcel to ecological, infrastructural, metropolitan, and regional relationships.", "children": [{"id": "3d3abca5-9fd8-4464-8929-df71d2c7cef9", "type": "subtopic", "title": "Infrastructure as landscape", "children": [{"id": "6cfa9d3e-91fd-41d8-9657-3f280fe8cd88", "type": "concept", "title": "Roads, utilities, stormwater, transit, rail, ports, energy, and digital networks"}, {"id": "3bcbfebf-ff37-4ec5-9d74-2ce168340f2a", "type": "concept", "title": "Visible and invisible systems"}, {"id": "4221f608-029b-4d89-9594-61a7aa24e481", "type": "concept", "title": "Infrastructure corridors as public realm and habitat"}], "description": "Students learn to see infrastructure as spatial and ecological design material."}, {"id": "71b8128b-45cc-481e-a0af-5780e46d0e23", "type": "subtopic", "title": "Mobility networks", "children": [{"id": "b2aa6b35-e61b-4070-a5ae-97b84d5c7806", "type": "concept", "title": "Walking, cycling, transit, vehicles, service, emergency access, and micromobility"}, {"id": "c51a5b95-1d5e-457d-bca8-e70737d36931", "type": "concept", "title": "First/last-mile connections"}, {"id": "47dbc299-abb2-4f15-9714-51edcaf79ed8", "type": "concept", "title": "Safety, equity, and mode shift"}], "description": "The gist is to connect site access to larger movement systems."}, {"id": "26827917-c5df-4c65-9670-26b1cefb42dd", "type": "subtopic", "title": "Regional systems", "children": [{"id": "8c4eca01-fb53-4387-b0b0-f5306275ebc9", "type": "concept", "title": "Greenways, blueways, food systems, heat islands, ecological corridors, and regional growth"}, {"id": "3415c0f5-756c-42ec-b7d0-53cf881e97a0", "type": "concept", "title": "Metropolitan scale and rural/urban edge"}, {"id": "0a486e38-2714-4063-8ac8-c562ee0cda06", "type": "concept", "title": "Scenario planning"}], "description": "Students broaden site thinking to watershed, habitat, economy, and settlement patterns."}]}, {"id": "2256459d-70ca-421a-937a-fe3a6977159e", "type": "topic", "title": "Zoning, Land Use, Entitlements, Codes, Easements, Utilities, and Development Feasibility", "description": "Students learn the regulatory and practical controls that affect what can be built, where, and under what approvals.", "children": [{"id": "414d4613-9854-40ce-ae23-5e3300258cd5", "type": "subtopic", "title": "Regulatory framework", "children": [{"id": "d12feb92-8445-4bd2-8194-38cefe1a4733", "type": "concept", "title": "Zoning district, use, setbacks, height, FAR, lot coverage, parking, loading, signage, and landscaping requirements"}, {"id": "ab8150bb-e30a-4d93-a035-cdba447d1acc", "type": "concept", "title": "Overlays, design review, and special districts"}, {"id": "1f61a76c-9d13-4e42-86bf-c1fab08cab8c", "type": "concept", "title": "Entitlements, variances, and approvals"}], "description": "Students learn the controls that shape buildable site strategy."}, {"id": "4692cffc-f0a3-4c5b-b18d-8537455d6376", "type": "subtopic", "title": "Property and utilities", "children": [{"id": "620ffe08-8946-4124-8c9d-176d6efb5540", "type": "concept", "title": "Property lines, easements, rights-of-way, setbacks, utilities, service corridors, and access agreements"}, {"id": "c629de6b-4c05-45b7-ba8a-3febc383f9f0", "type": "concept", "title": "Survey, title, and civil coordination"}, {"id": "adc62068-0f03-4963-95e4-432e35deb11f", "type": "concept", "title": "Utility capacity and relocation"}], "description": "The point is to identify hidden constraints before design decisions harden."}, {"id": "9e80f79a-2013-4884-8337-8a640bfd57ff", "type": "subtopic", "title": "Feasibility and risk", "children": [{"id": "706d6dec-7b47-4b01-a026-2ae91cfa6cac", "type": "concept", "title": "Development yield, phasing, cost, constructability, permitting schedule, and stakeholder risk"}, {"id": "f47a4807-933e-45c2-83eb-a23a3ee166de", "type": "concept", "title": "Environmental review and community review"}, {"id": "66f2bf91-4801-4583-8a3e-2325787a167d", "type": "concept", "title": "Feasibility matrices and decision logs"}], "description": "Students connect site planning to project viability."}]}, {"id": "ad602fd0-7a10-4343-8666-336b3fee8ce2", "type": "topic", "title": "Sustainable Site Design: Heat, Carbon, Biodiversity, Resilience, Equity, and Climate Adaptation", "description": "This topic integrates sustainable design goals with measurable performance, climate risk, public health, and social value.", "children": [{"id": "17136a69-494c-4017-abaa-58cd848f4a37", "type": "subtopic", "title": "Climate adaptation", "children": [{"id": "7c4ff9a1-c1a1-46a4-bfd1-0ebd2032249d", "type": "concept", "title": "Extreme heat, flooding, drought, wildfire, storms, sea-level rise, and air quality"}, {"id": "92742b27-5f6b-42ad-ba91-b7d1174a516c", "type": "concept", "title": "Redundancy, refuge, shade, drainage, and emergency access"}, {"id": "fb1650e3-db6d-427c-9563-780eeae94ae2", "type": "concept", "title": "Adaptation strategies at parcel and district scales"}], "description": "Students learn to design sites for changing risk conditions."}, {"id": "b98c9335-3d64-4735-a18a-a7ee910a9b04", "type": "subtopic", "title": "Low-carbon site design", "children": [{"id": "988aacfb-d34e-444a-8982-0aa5e4661ec4", "type": "concept", "title": "Earthwork minimization, material reuse, low-carbon paving, tree preservation, and soil carbon"}, {"id": "21785289-0d04-4ce4-9173-9235ede933fb", "type": "concept", "title": "Construction disturbance and lifecycle thinking"}, {"id": "09849ebf-ee40-47d5-81ca-7d317f1ac443", "type": "concept", "title": "Landscape maintenance emissions"}], "description": "The gist is to reduce embodied and operational impacts of site work."}, {"id": "32222d55-90b5-4554-845d-95108bb07e67", "type": "subtopic", "title": "Equity and environmental justice", "children": [{"id": "31ca2dc2-3257-4671-aa0e-b96f124c54b7", "type": "concept", "title": "Access to shade, parks, mobility, clean water, safety, and public amenities"}, {"id": "dd27f666-17c9-4d89-a4d3-2ba946f3db65", "type": "concept", "title": "Heat-vulnerable populations and historic disinvestment"}, {"id": "3d0dfa3d-0df6-4614-904b-96cef66ad2bc", "type": "concept", "title": "Community benefits and anti-displacement awareness"}], "description": "Students connect sustainability to people and power."}]}, {"id": "c70e870d-caca-4569-b2df-156f9187ea8c", "type": "topic", "title": "Representation and Digital Site Tools: Survey, GIS, Diagrams, Models, Sections, and Performance Metrics", "description": "Students learn to communicate site intelligence through maps, diagrams, drawings, models, and evidence-based metrics.", "children": [{"id": "aa7ca87c-7f11-40ca-a3d3-4f9518f83ff1", "type": "subtopic", "title": "Survey and base data", "children": [{"id": "10042328-f91f-4def-864f-0dacbf0adeea", "type": "concept", "title": "Topographic surveys, GIS layers, aerial imagery, LiDAR, soil maps, flood maps, and census data"}, {"id": "bf587ba7-78c9-445d-bd88-dd0536d8b91d", "type": "concept", "title": "Datum, scale, accuracy, and source reliability"}, {"id": "ec63f3b9-3255-4907-86ba-d874878cca62", "type": "concept", "title": "Data cleaning and attribution"}], "description": "Students learn to work from reliable site information."}, {"id": "ccbee760-e46f-4710-ad74-6b6561d2e043", "type": "subtopic", "title": "Drawings and diagrams", "children": [{"id": "0b06a4fc-11b7-47ea-8faa-6e2bb7655fee", "type": "concept", "title": "Maps, sections, axonometrics, slope diagrams, sun/wind diagrams, hydrology diagrams, and circulation diagrams"}, {"id": "ff1af2f2-6c3f-4e6e-b49a-0730f011b742", "type": "concept", "title": "Graphic hierarchy and annotation"}, {"id": "b1085c40-435a-416d-bcb3-629b2435a632", "type": "concept", "title": "From analysis drawing to design drawing"}], "description": "The point is to communicate site logic clearly."}, {"id": "a7bd4b10-86d9-48ff-ae85-04869b3bec7e", "type": "subtopic", "title": "Models and metrics", "children": [{"id": "9c7c3433-24c8-4f47-b79d-0a57bbe188b6", "type": "concept", "title": "Physical models, digital terrain models, massing models, GIS, daylight/shadow studies, stormwater estimates, and landscape-performance metrics"}, {"id": "f1134f17-fcab-4a3b-a677-261fa8ca1bc7", "type": "concept", "title": "Iteration and evidence"}, {"id": "00c0e45f-8f68-410e-8faf-9c7bee56f046", "type": "concept", "title": "Limitations of simulation"}], "description": "Students use tools to test rather than merely illustrate."}]}, {"id": "1fa020c9-d5d3-4bfc-ad03-2f41d4887820", "type": "topic", "title": "Site as Program and Community: Stakeholders, Public Life, Cultural Landscape, and Participatory Design", "description": "This module treats site as social and cultural territory shaped by communities, histories, use patterns, memory, and power.", "children": [{"id": "15c2e83c-6d9a-4aad-ae90-486f5f9a78c2", "type": "subtopic", "title": "Stakeholders and users", "children": [{"id": "9ade4ab3-7d13-4e55-9bc3-10b8beacc3cd", "type": "concept", "title": "Residents, workers, visitors, owners, agencies, maintenance staff, and marginalized users"}, {"id": "11378073-d1af-4a89-8a86-002a245f12b0", "type": "concept", "title": "Interviews, observation, workshops, and surveys"}, {"id": "33bc68ff-0cb5-4835-9faf-da0e2c9351ef", "type": "concept", "title": "Representation, consent, and interpretation"}], "description": "Students learn whose site knowledge matters."}, {"id": "54fd527e-187d-4296-942d-64582c7d2ccc", "type": "subtopic", "title": "Cultural landscape", "children": [{"id": "0a481017-dac8-4a3f-a5dc-b2b917a22ccf", "type": "concept", "title": "Historic layers, rituals, public art, informal uses, indigenous histories, and contested narratives"}, {"id": "cdc0b675-a1ca-4d27-8fad-23e5144761df", "type": "concept", "title": "Preservation, adaptation, and interpretation"}, {"id": "14e5174c-543a-47db-aa46-eca8034d4de3", "type": "concept", "title": "Avoiding erasure through design"}], "description": "The gist is to see sites as carriers of memory and identity."}, {"id": "68259f86-fdc8-4cc6-8670-509f97f2320f", "type": "subtopic", "title": "Participation and stewardship", "children": [{"id": "37b3c922-ea11-425e-8791-4fa0f7792092", "type": "concept", "title": "Co-design, maintenance partnerships, programming, governance, and community stewardship"}, {"id": "1dbef02c-e519-4fcb-b17a-e1a900fb8b45", "type": "concept", "title": "Temporary activation and tactical urbanism"}, {"id": "7746f754-2a1e-4592-b08e-47e019f86bc4", "type": "concept", "title": "Measuring social value"}], "description": "Students connect design to long-term care and public life."}]}, {"id": "868a5e05-02b5-4423-9729-745fa5594916", "type": "topic", "title": "Integrated Site Strategy Capstone: From Analysis to Landscape-Architectural Design Proposal", "description": "Students synthesize the course by producing a site strategy and design proposal that connects analysis, ecology, access, program, and architectural intent.", "children": [{"id": "41498213-c3b0-4e9b-8b06-301ce2c67471", "type": "subtopic", "title": "Research synthesis", "children": [{"id": "8deaa81c-e15b-4eda-a4ca-1d416dfccc80", "type": "concept", "title": "Inventory atlas, constraints/opportunities, stakeholder findings, regulatory matrix, and performance goals"}, {"id": "67ef28d3-af78-4fd6-9ea5-1a047d850c78", "type": "concept", "title": "Design priorities and tradeoffs"}, {"id": "fbacd725-6b89-4634-b9a5-8687f7fd2ae5", "type": "concept", "title": "Concept statement and criteria"}], "description": "Students turn all site evidence into a clear design argument."}, {"id": "55417b4b-8256-44c3-9544-c91d01408fa8", "type": "subtopic", "title": "Design proposal", "children": [{"id": "769da754-9e32-4717-8efe-8faa3a4b5d1e", "type": "concept", "title": "Site plan, grading concept, stormwater strategy, planting concept, hardscape, circulation, and outdoor rooms"}, {"id": "9202cad6-f631-40b9-ab46-96b3c19d8796", "type": "concept", "title": "Architecture-ground relationship"}, {"id": "a0bb68d1-d3ba-485e-979f-d34c61e26f5a", "type": "concept", "title": "Phasing and constructability"}], "description": "The point is to integrate building, landscape, ecology, and access."}, {"id": "fc248398-d056-4a01-8d13-33fbe4b6a010", "type": "subtopic", "title": "Final communication package", "children": [{"id": "d1c3b68b-cb03-48b9-abd2-a1bd14e84240", "type": "concept", "title": "Plans, sections, diagrams, precedent references, material palette, metrics, and narrative"}, {"id": "efc04967-9099-4e25-9f9b-00fff99da10e", "type": "concept", "title": "Critique response and revision"}, {"id": "9909c64c-c5da-45a3-a3b1-77ea193d36c5", "type": "concept", "title": "Portfolio-ready presentation"}], "description": "Students produce a review-ready set of deliverables."}]}], "dbBacked": true}$sitejson$::jsonb,
