  ('e67a9e7a-aa09-4946-971f-a2ff363377c5', 'b8c9d0e1-2f3a-4c02-9f12-2d3e4f5a6b22', 'cf061be7-ac6f-45a6-bb17-a55dcb69ed58', 'subtopic'::public.curated_course_node_type, 'Site as active design agent', 'Students learn to treat site conditions as generators of architecture, not limits to be added after the fact.', 0),
